import{_ as l,a0 as r,w as i,s,ao as o,I as p,x as u,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Apple Watch之後，下一個智能手錶會是Ubuntu嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Apple Watch之後，下一個智能手錶會是Ubuntu嗎？ | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Apple Watch之後，下一個智能手錶會是Ubuntu嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Apple Watch之後，下一個智能手錶會是Ubuntu嗎？ | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20140910 With Apple Watch Unveiled, Could an Ubuntu Smartwatch Be Next","title":"Apple Watch之後，下一個智能手錶會是Ubuntu嗎？","tag":"201501","desc":""},"relativePath":"201501/20140910 With Apple Watch Unveiled, Could an Ubuntu Smartwatch Be Next.md","filePath":"[post].md"}'),b={name:"201501/20140910 With Apple Watch Unveiled, Could an Ubuntu Smartwatch Be Next.md"};function d(m,t,h,U,w,T){const n=r("Link");return i(),s("div",null,[t[19]||(t[19]=o('<h1 id="apple-watch之後-下一個智能手錶會是ubuntu嗎" tabindex="-1">Apple Watch之後，下一個智能手錶會是Ubuntu嗎？ <a class="header-anchor" href="#apple-watch之後-下一個智能手錶會是ubuntu嗎" aria-label="Permalink to “Apple Watch之後，下一個智能手錶會是Ubuntu嗎？”">​</a></h1><p><strong>蘋果藉助‘Apple Watch’的發佈，證實了其進軍穿戴式電子設備市場的長期傳言</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/ubuntu-galaxy-gear-smartwatch.png" alt="Ubuntu Smartwatch – good idea?"></p><p>Ubuntu智能手錶 - 好主意？</p><p>擁有一系列穩定功能、硬件解決方案和應用合作伙伴關係的支持，手腕穿戴設備被許多公司預示為“人與技術關係的新篇章”。</p><p>它的到來，以及用户興趣的提升，有可能意味着Ubuntu需要跟進一個為智能手錶定製的Ubuntu版本。</p><h3 id="大的方面還是成功的" tabindex="-1">大的方面還是成功的 <a class="header-anchor" href="#大的方面還是成功的" aria-label="Permalink to “大的方面還是成功的”">​</a></h3><p>蘋果在正確的時間加入了快速發展的智能手錶行列。手腕穿戴設備功能的界限並不是一成不變。失敗的設計、簡陋的用户界面以及主流用户使用穿戴技術功能的弱定製化，這些都見證了硬件類產品仍然很脆弱 － 這一因素使得Cupertino把時間花費在Apple Watch上。</p><blockquote><p>‘分析師説：超過2200萬的智能手錶將在今年銷售’</p></blockquote><p>去年全球範圍內可穿戴設備的銷售數量（包括健身追蹤器）僅僅1000萬。今年，分析師希望設備的銷量可以超過2200萬 － 不包括蘋果手錶，因為其直到2015年初才開始零售。</p><p>其實，我們很容易就可以看出增長的來源。今年九月初柏林舉辦的IFA 2014展覽會，展示了一系列來自主要製造商們的可穿戴設備，包括索尼和華碩。大多數搭載着Google最新發布的安卓穿戴平台。</p><p>更成熟的一個表現是：安卓穿戴設備打破了與形式因素保持一致的新奇爭論，進而呈現出一致且令人信服的用户方案。和新的蘋果手錶一樣，它緊密地連接在一個現存的智能手機生態系統上。</p><p>但Ubuntu手腕穿戴系統是否能與之匹配，成為一個實用案例，目前還不清楚。</p><h4 id="目前還沒有ubuntu智能手錶的計劃" tabindex="-1">目前還沒有Ubuntu智能手錶的計劃 <a class="header-anchor" href="#目前還沒有ubuntu智能手錶的計劃" aria-label="Permalink to “目前還沒有Ubuntu智能手錶的計劃”">​</a></h4><p>Ubuntu操作系統的通用性將多種設備的嚴格標準與統一的未來目標聯合在一起，Canonical已經將目標指向了智能電視，平板電腦和智能手機。公司自家的顯示服務Mir，甚至被用來為所有尺寸的屏幕提供驅動接口（雖然不是公認1.5&quot;的）。</p><p>今年年初，Canonical社區負責人Jono Bacon被問到是否有製作Ubuntu智能手錶的打算。Bacon提供了他對這個問題的看法：“為[Ubuntu觸摸設備]路線增加額外的形式因素只會減緩現有的進度”。</p><p>在Ubuntu手機發布兩週年之際，我們還是挺贊同他的想法的。</p><p>###除了A面還有B面！###</p>',18)),p("p",null,[t[1]||(t[1]=u("但是並不是沒有希望的。在",-1)),a(n,{href:"http://www.omgubuntu.co.uk/2014/03/ubuntu-tablets-coming-year"},{default:e(()=>[...t[0]||(t[0]=[u("幾個月之後的一次電話採訪",-1)])]),_:1}),t[2]||(t[2]=u("中，Ubuntu創始人Mark Shuttleworth提到，可穿戴技術和智能電視、平板電腦、智能手機一樣，都在公司計劃當中。",-1))]),t[20]||(t[20]=o('<blockquote><p>“Ubuntu因其在電話中的完美設計變得獨一無二，但同時它的設計也能夠滿足其他生態系統，從穿戴設備到PC機。”</p></blockquote><p>然而這還沒得到具體的證實，它更像一個指針，在某個方向給我們提供一個樂觀的指引。</p><h4 id="不大可能-—-但這就是原因所在" tabindex="-1">不大可能 — 但這就是原因所在 <a class="header-anchor" href="#不大可能-—-但這就是原因所在" aria-label="Permalink to “不大可能 — 但這就是原因所在”">​</a></h4><p>Canonical並不反對利用牢固的專利進軍市場。事實上，它恰恰是公司DNA基因的一部分 — 猶如服務器端的RHEL,桌面端的Windows,智能手機上的安卓...</p><p>設備上的Ubuntu系統被製作成可以在更小的屏幕上擴展和適配運行，甚至在小如手錶一樣的屏幕上。當普通的代碼基礎已經在手機、平板電腦、桌面和TV上準備就緒，在同樣的方向上，如果看不到社區的努力是十分令人吃驚的。</p><p>但是我之所以不認為它會從Canonical發生，至少目前還沒有，是基於今年早些時候Jono Bacon的個人思想得出的結論：時間和努力。</p><p>Tim Cook在他的主題演講中説道：“<em>我們並沒有追隨iPhone，也沒有縮水用户界面，將其強硬捆綁在你的手腕上。</em>”這是一個很明顯的陳述。為如此小的屏幕設計UI和UX模型、通過交互原則工作、對硬件和輸入模式的推崇，這些都不是容易的事。</p><p>可穿戴技術仍然是一個新興的市場。在這個階段，Canonical可能會在探尋的過程中浪費一些發展、設計和商業上的機會。如果在一些更為緊迫的領域落後了，造成的後果遠比眼前利益的損失更嚴重。</p><p>打一場持久戰，耐心等待，看哪些努力成功哪些會失敗，這是一條更難的路線，但是卻更適合Ubuntu，就如同今天它做的一樣。在新產品出現之前，Canonical把力量用在現存的產品上是更好的選擇（這是一些已經來遲的理論）</p>',9)),p("p",null,[t[4]||(t[4]=u("想更進一步瞭解什麼是Ubuntu智能手錶，點擊下面的",-1)),a(n,{href:"https://www.youtube.com/embed/8Zf5dktXzEs?feature=oembed"},{default:e(()=>[...t[3]||(t[3]=[u("視頻",-1)])]),_:1}),t[5]||(t[5]=u("，裏面展示了一個交互的Unity主題皮膚Tizen(它已經支持Samsung Galaxy Gear智能手錶)。",-1))]),t[21]||(t[21]=p("hr",null,null,-1)),p("p",null,[t[7]||(t[7]=u("via: ",-1)),a(n,{href:"http://www.omgubuntu.co.uk/2014/09/ubuntu-smartwatch-apple-iwatch"},{default:e(()=>[...t[6]||(t[6]=[u("http://www.omgubuntu.co.uk/2014/09/ubuntu-smartwatch-apple-iwatch",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=u("作者：",-1)),a(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:e(()=>[...t[8]||(t[8]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[12]||(t[12]=u(" 譯者：",-1)),a(n,{href:"https://github.com/su-kaiyao"},{default:e(()=>[...t[9]||(t[9]=[u("su-kaiyao",-1)])]),_:1}),t[13]||(t[13]=u(" 校對：",-1)),a(n,{href:"https://github.com/tinyeyeser"},{default:e(()=>[...t[10]||(t[10]=[u("Mr小眼兒",-1)])]),_:1})]),p("p",null,[t[16]||(t[16]=u("本文由",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[14]||(t[14]=[u("LCTT",-1)])]),_:1}),t[17]||(t[17]=u(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:e(()=>[...t[15]||(t[15]=[u("Linux中國",-1)])]),_:1}),t[18]||(t[18]=u(" 榮譽推出",-1))])])}const A=l(b,[["render",d]]);export{g as __pageData,A as default};
